package dev.shadw.asgard.mobs;

import dev.shadw.asgard.Sleipnir;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Sleipnir with its own model and texture. Generated by shadw-mod mob. */
public class SleipnirRenderer extends MobRenderer<Sleipnir, SleipnirModel.State, SleipnirModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/sleipnir.png");

	public SleipnirRenderer(EntityRendererProvider.Context context) {
		super(context, new SleipnirModel(context.bakeLayer(SleipnirModel.LAYER)), 1.0F);
	}

	@Override
	public SleipnirModel.State createRenderState() {
		return new SleipnirModel.State();
	}

	@Override
	public void extractRenderState(Sleipnir entity, SleipnirModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(SleipnirModel.State state) {
		return TEXTURE;
	}
}
